import {drawQrImage} from './qr-image.js';
import {eventLink} from './event-link.js';
export function mountEventShare(root,event){
 const panel=document.createElement('section');panel.className='panel';const title=document.createElement('h3');title.textContent='QR สมัครกิจกรรม';const hint=document.createElement('p');hint.className='sub';hint.textContent='นำไปติดโปสเตอร์หรือแชร์ให้ผู้สมัคร · ใช้สำหรับเปิดรายละเอียดและสมัคร ไม่ใช่บัตรเช็คอิน';const open=document.createElement('button');open.className='primary';open.textContent='แสดง QR / ดาวน์โหลด';panel.append(title,hint,open);root.append(panel);
 open.onclick=async()=>{const modal=document.querySelector('#modal'),body=document.querySelector('#modalBody');body.replaceChildren();const heading=document.createElement('h2');heading.textContent='QR สมัครกิจกรรม';const name=document.createElement('p');name.textContent=event.name;const canvas=document.createElement('canvas');canvas.style.cssText='max-width:100%;height:auto;display:block;margin:auto';canvas.setAttribute('aria-label','QR เปิดรายละเอียดกิจกรรม '+event.name);const input=document.createElement('input');input.className='event-share-link';input.readOnly=true;input.value=eventLink(event.id);input.setAttribute('aria-label','ลิงก์กิจกรรม');const status=document.createElement('p');status.setAttribute('role','status');body.append(heading,name,canvas,input,status);modal.showModal();
 try{const qr=await import('./vendor/qr.js');if(!canvas.isConnected||!modal.open)return;await drawQrImage(canvas,input.value,qr.default);if(!canvas.isConnected||!modal.open)return;const save=document.createElement('a');save.className='catalog-action event-share-action';save.textContent='ดาวน์โหลด QR (PNG)';save.download='KUSK-event-'+event.id+'.png';save.href=canvas.toDataURL('image/png');const copy=document.createElement('button');copy.className='event-share-action';copy.textContent='คัดลอกลิงก์';copy.onclick=async()=>{try{await navigator.clipboard.writeText(input.value);status.textContent='คัดลอกลิงก์แล้ว'}catch{input.focus();input.select();status.textContent='กดค้างที่ลิงก์เพื่อคัดลอก'}};const preview=document.createElement('a');preview.className='event-share-action';preview.href=input.value;preview.target='_blank';preview.rel='noopener';preview.textContent='เปิดหน้าที่ผู้สมัครจะเห็น ↗';body.append(save,copy,preview);status.textContent=event.published&&!event.deleted?'สแกนเพื่อดูรายละเอียดกิจกรรมและสมัคร':'กิจกรรมนี้ยังไม่เผยแพร่ ผู้สมัครจะเห็นข้อความว่าไม่เปิดให้บริการ';}catch{status.textContent='สร้างภาพ QR ไม่สำเร็จ กรุณาปิดแล้วลองใหม่ หรือนำลิงก์ด้านบนไปใช้'}
 };
}
